import sys
from collections import deque

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    if m != n:
        print("NO")
        return

    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * (n + 1)
    q = deque()
    start_node = 1
    visited[start_node] = True
    q.append(start_node)
    count = 0

    while q:
        u = q.popleft()
        count += 1
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                q.append(v)

    if count != n:
        print("NO")
    else:
        print("FHTAGN!")

if __name__ == "__main__":
    main()
